-- Post-deployment (idempotent reference data)
-- ==================================================================================================

-- >>> source: postgres/postdeploy/10_applications_db_schema.sql

-- =====================================================================
-- Post-deployment: app.applications.db_schema - the schema of each app's own invoice tables.
-- Idempotent backfill (only rows still NULL). The application rows themselves come from seed.sql.
-- =====================================================================
UPDATE app.applications
SET db_schema = CASE lower(code) WHEN 'gp' THEN 'gpp' WHEN 'sjo' THEN 'sjo' WHEN 'rospbu' THEN 'rospbu' END
WHERE db_schema IS NULL
  AND lower(code) IN ('gp', 'sjo', 'rospbu');


-- >>> source: postgres/postdeploy/20_statuses.sql

-- =====================================================================
-- Post-deployment: the core invoice workflow statuses (system data, required by existing invoices).
-- Idempotent: inserts missing rows only; names / colours edited in Settings > Configuration are kept.
-- =====================================================================
INSERT INTO app.statuses (code, name, description, color, sort_order) VALUES
    ('Pending',   'Pending',   'Received, waiting for review',  'warning', 10),
    ('Approved',  'Approved',  'Reviewed and approved',         'success', 20),
    ('Processed', 'Processed', 'Posted for payment',            'info',    30),
    ('Rejected',  'Rejected',  'Rejected during review',        'danger',  40)
ON CONFLICT (code) DO NOTHING;


